// Every status-specific error keeps an optional cause. The cause lives in the shared
// ApiError base that each typed error embeds, so every typed error reports the same
// cause through Cause and errors.Is, and a response built without one has none.
func TestBhvErrors003_ApiError_EveryStatusSpecificErrorKeepsAnOptionalCause(t *testing.T) {
	t.Parallel()
	type causer interface{ Cause() error }
	cause := errors.New("connection reset by peer")
	base := *apierrors.NewApiError(500, "boom", "", nil, nil, cause)
	typed := map[string]error{
		"ClientError":               &apierrors.ClientError{ApiError: base},
		"BadRequestError":           &apierrors.BadRequestError{ClientError: apierrors.ClientError{ApiError: base}},
		"UnauthorizedError":         &apierrors.UnauthorizedError{ClientError: apierrors.ClientError{ApiError: base}},
		"ForbiddenError":            &apierrors.ForbiddenError{ClientError: apierrors.ClientError{ApiError: base}},
		"NotFoundError":             &apierrors.NotFoundError{ClientError: apierrors.ClientError{ApiError: base}},
		"ConflictError":             &apierrors.ConflictError{ClientError: apierrors.ClientError{ApiError: base}},
		"UnprocessableEntityError":  &apierrors.UnprocessableEntityError{ClientError: apierrors.ClientError{ApiError: base}},
		"TooManyRequestsError":      &apierrors.TooManyRequestsError{ClientError: apierrors.ClientError{ApiError: base}},
		"PaymentRequiredError":      &apierrors.PaymentRequiredError{ClientError: apierrors.ClientError{ApiError: base}},
		"MethodNotAllowedError":     &apierrors.MethodNotAllowedError{ClientError: apierrors.ClientError{ApiError: base}},
		"RequestTimeoutError":       &apierrors.RequestTimeoutError{ClientError: apierrors.ClientError{ApiError: base}},
		"GoneError":                 &apierrors.GoneError{ClientError: apierrors.ClientError{ApiError: base}},
		"PayloadTooLargeError":      &apierrors.PayloadTooLargeError{ClientError: apierrors.ClientError{ApiError: base}},
		"UnsupportedMediaTypeError": &apierrors.UnsupportedMediaTypeError{ClientError: apierrors.ClientError{ApiError: base}},
		"LockedError":               &apierrors.LockedError{ClientError: apierrors.ClientError{ApiError: base}},
		"ServerError":               &apierrors.ServerError{ApiError: base},
		"InternalServerError":       &apierrors.InternalServerError{ServerError: apierrors.ServerError{ApiError: base}},
		"NotImplementedError":       &apierrors.NotImplementedError{ServerError: apierrors.ServerError{ApiError: base}},
		"BadGatewayError":           &apierrors.BadGatewayError{ServerError: apierrors.ServerError{ApiError: base}},
		"ServiceUnavailableError":   &apierrors.ServiceUnavailableError{ServerError: apierrors.ServerError{ApiError: base}},
		"GatewayTimeoutError":       &apierrors.GatewayTimeoutError{ServerError: apierrors.ServerError{ApiError: base}},
	}
	for name, err := range typed {
		c, ok := err.(causer)
		if !ok {
			t.Errorf("%s does not expose Cause()", name)
			continue
		}
		if c.Cause() != cause {
			t.Errorf("%s: expected the cause it was built with, got %v", name, c.Cause())
		}
		if !errors.Is(err, cause) {
			t.Errorf("%s: expected errors.Is to reach the cause", name)
		}
	}
	if c, ok := apierrors.FromResponse(404, nil, "").(causer); !ok || c.Cause() != nil {
		t.Errorf("expected a response error built without a cause to have none, got %v", c)
	}
}

// Error() renders the message first and then each part that is present on its
// own line; an absent part leaves no empty line behind, and an empty message
// falls back to the generic sentence.
func TestBhvErrors088_ApiError_ErrorRendersOnlyThePartsThatArePresent(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		err  *apierrors.ApiError
		want string
	}{
		{
			"every part",
			apierrors.NewApiError(502, "bad gateway", "upstream down", map[string]string{"retry-after": "5"}, nil, nil),
			"bad gateway\nHTTP status code: 502\nResponse headers: {\"retry-after\":\"5\"}\nResponse body: upstream down",
		},
		{
			"headers are compact JSON with sorted keys and no HTML escaping",
			apierrors.NewApiError(200, "m", "", map[string]string{"b": "<2>", "a": "1"}, nil, nil),
			"m\nHTTP status code: 200\nResponse headers: {\"a\":\"1\",\"b\":\"<2>\"}",
		},
		{
			"empty headers and body are omitted",
			apierrors.NewApiError(404, "missing", "", map[string]string{}, nil, nil),
			"missing\nHTTP status code: 404",
		},
		{
			"status zero is omitted",
			apierrors.NewApiError(0, "connection reset", "", nil, nil, nil),
			"connection reset",
		},
		{
			"empty message falls back",
			apierrors.NewApiError(500, "", "", nil, nil, nil),
			"Error message: the server returns an error\nHTTP status code: 500",
		},
	}
	for _, tc := range cases {
		if got := tc.err.Error(); got != tc.want {
			t.Errorf("%s: expected %q, got %q", tc.name, tc.want, got)
		}
	}
}

// Error() shows at most 1 KiB of the body, escapes control characters so a
// hostile body cannot forge a log line, and masks credential-bearing response
// headers; the accessors keep the real body and headers.
func TestBhvErrors001_ApiError_ErrorCapsTheBodyEscapesControlsAndMasksSecretHeaders(t *testing.T) {
	t.Parallel()
	long := strings.Repeat("x", 1030)
	capped := apierrors.NewApiError(500, "boom", long, nil, nil, nil)
	if got, want := capped.Error(), "boom\nHTTP status code: 500\nResponse body: "+strings.Repeat("x", 1024)+"... (6 more bytes)"; got != want {
		t.Errorf("expected the body capped at 1024 bytes, got %q", got)
	}
	if capped.ResponseBody() != long {
		t.Error("the full body must stay on ResponseBody")
	}

	multibyte := strings.Repeat("x", 1023) + "\u00e9"
	cut := apierrors.NewApiError(500, "boom", multibyte, nil, nil, nil)
	if got, want := cut.Error(), "boom\nHTTP status code: 500\nResponse body: "+strings.Repeat("x", 1023)+"... (2 more bytes)"; got != want {
		t.Errorf("expected the cap to stop before a split character, got %q", got)
	}

	forged := apierrors.NewApiError(500, "boom", "a\r\nHTTP status code: 200\x00\x7f", nil, nil, nil)
	if got, want := forged.Error(), "boom\nHTTP status code: 500\nResponse body: a\\x0D\\x0AHTTP status code: 200\\x00\\x7F"; got != want {
		t.Errorf("expected control characters escaped, got %q", got)
	}

	headers := map[string]string{
		"Authorization":       "Bearer a",
		"Proxy-Authorization": "Basic b",
		"Cookie":              "sid=c",
		"set-cookie":          "sid=d",
		"www-authenticate":    "Bearer realm=x",
		"proxy-authenticate":  "Basic realm=y",
		"x-api-key":           "k",
		"x-auth-token":        "t",
		"x-client-secret":     "s",
		"x-request-id":        "abc",
	}
	masked := apierrors.NewApiError(401, "denied", "", headers, nil, nil)
	want := "denied\nHTTP status code: 401\nResponse headers: " +
		`{"Authorization":"***","Cookie":"***","Proxy-Authorization":"***","proxy-authenticate":"***",` +
		`"set-cookie":"***","www-authenticate":"***","x-api-key":"***","x-auth-token":"***",` +
		`"x-client-secret":"***","x-request-id":"abc"}`
	if got := masked.Error(); got != want {
		t.Errorf("expected credential headers masked, got %q", got)
	}
	if masked.ResponseHeaders()["set-cookie"] != "sid=d" {
		t.Error("the real header values must stay on ResponseHeaders")
	}
}

// FromResponse keeps whatever JSON the server sent as the error body, scalars
// and a leading byte order mark included, and never fails on a body it cannot
// parse: the raw body is still retained.
func TestBhvErrors008_ApiError_FromResponse_ParsesScalarAndBomPrefixedBodies(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		body string
		want any
	}{
		{"string scalar", `"plain text"`, "plain text"},
		{"number scalar", `42`, float64(42)},
		{"byte order mark before an object", "\xEF\xBB\xBF{\"k\":\"v\"}", map[string]any{"k": "v"}},
		{"not json", `<html>oops</html>`, nil},
	}
	for _, tc := range cases {
		var apiErr *apierrors.ApiError
		err := apierrors.FromResponse(500, nil, tc.body)
		if !errors.As(err, &apiErr) {
			t.Fatalf("%s: expected *ApiError, got %T", tc.name, err)
		}
		if !reflect.DeepEqual(apiErr.ErrorBody(), tc.want) {
			t.Errorf("%s: expected error body %#v, got %#v", tc.name, tc.want, apiErr.ErrorBody())
		}
		if apiErr.ResponseBody() != tc.body {
			t.Errorf("%s: expected the raw body to be kept, got %q", tc.name, apiErr.ResponseBody())
		}
	}
}

